from pathlib import Path
import re

page = Path('app/page.tsx')
s = page.read_text()

new_modal = r'''function EventModal({clients,event,onClose,onSaved}:any){const allowedStatuses=['preventivo_inviato','confermato','annullato'];const initialStatus=allowedStatuses.includes(event?.status)?event.status:'preventivo_inviato';const [form,setForm]=useState({client_id:event?.client_id||'',event_date:event?.event_date||new Date().toISOString().slice(0,10),service:event?.service||'cena',adults:event?.adults??0,baby:event?.baby??0,status:initialStatus,price_per_adult:event?.price_per_adult??'',price_per_baby:event?.price_per_baby??'',internal_notes:event?.internal_notes||''});const [saving,setSaving]=useState(false);async function save(e:FormEvent){e.preventDefault();if(!supabase)return;setSaving(true);const payload={client_id:form.client_id||null,event_date:form.event_date,service:form.service,adults:Number(form.adults),baby:Number(form.baby),status:form.status,price_per_adult:form.price_per_adult===''?null:Number(form.price_per_adult),price_per_baby:form.price_per_baby===''?null:Number(form.price_per_baby),internal_notes:form.internal_notes};const res=event?await supabase.from('events').update(payload).eq('id',event.id):await supabase.from('events').insert(payload);setSaving(false);if(!res.error){await onSaved();onClose()}else alert(res.error.message)}return <Modal title={event?`Evento #${event.event_number}`:'Nuovo evento'} onClose={onClose} wide><form onSubmit={save} className="formGrid eventForm"><label className="eventClientField">Cliente<select value={form.client_id} onChange={e=>setForm({...form,client_id:e.target.value})}><option value="">Seleziona cliente</option>{clients.map((c:Client)=><option key={c.id} value={c.id}>{nameOfClient(c)}</option>)}</select></label><div className="eventTopRow"><label>Data<input type="date" value={form.event_date} onChange={e=>setForm({...form,event_date:e.target.value})} required/></label><label>Servizio<select value={form.service} onChange={e=>setForm({...form,service:e.target.value})}><option value="pranzo">Pranzo</option><option value="cena">Cena</option><option value="altro">Altro</option></select></label><label>Stato<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option value="preventivo_inviato">Preventivo inviato</option><option value="confermato">Confermato</option><option value="annullato">Annullato</option></select></label></div><div className="eventPairRow"><label>Adulti<input type="number" min="0" value={form.adults} onChange={e=>setForm({...form,adults:e.target.value as any})}/></label><label>Baby<input type="number" min="0" value={form.baby} onChange={e=>setForm({...form,baby:e.target.value as any})}/></label></div><div className="eventPairRow"><label>Prezzo per persona €<input type="number" step="0.01" min="0" value={form.price_per_adult} onChange={e=>setForm({...form,price_per_adult:e.target.value as any})}/></label><label>Prezzo menu baby €<input type="number" step="0.01" min="0" value={form.price_per_baby} onChange={e=>setForm({...form,price_per_baby:e.target.value as any})}/></label></div><label className="span2">Note interne<textarea rows={4} value={form.internal_notes} onChange={e=>setForm({...form,internal_notes:e.target.value})}/></label><div className="formActions span2"><button type="button" className="ghost" onClick={onClose}>Annulla</button><button className="primary" disabled={saving}>{saving?'Salvataggio…':'Salva evento'}</button></div></form></Modal>}'''
s, n = re.subn(r'function EventModal\(\{clients,event,onClose,onSaved\}:any\).*?(?=function ClientModal)', new_modal + '\n', s, count=1, flags=re.S)
if n != 1: raise SystemExit('EventModal non trovato')

new_ingredient = r'''function IngredientModal({ingredient,units,onClose,onSaved}:{ingredient:Ingredient|null;units:Unit[];onClose:()=>void;onSaved:()=>Promise<void>}){const [f,setF]=useState({name:ingredient?.name||'',category:ingredient?.category||'',current_price:ingredient?.current_price?.toString()||'',unit_id:ingredient?.unit_id||''});const [saving,setSaving]=useState(false);const [usedBy,setUsedBy]=useState<{id:string;name:string;category:string|null}[]>([]);useEffect(()=>{if(!ingredient||!supabase){setUsedBy([]);return}supabase.from('recipe_ingredients').select('recipe:recipes(id,name,category)').eq('ingredient_id',ingredient.id).then(({data})=>{const rows=(data||[]).map((x:any)=>x.recipe).filter(Boolean);const unique=Array.from(new Map(rows.map((r:any)=>[r.id,r])).values()) as {id:string;name:string;category:string|null}[];setUsedBy(unique)})},[ingredient?.id]);async function save(e:FormEvent){e.preventDefault();if(!supabase)return;setSaving(true);const price=Number(f.current_price||0);const payload={name:f.name,category:f.category||null,current_price:price,current_price_date:new Date().toISOString().slice(0,10),unit_id:f.unit_id||null};const res=ingredient?await supabase.from('ingredients').update(payload).eq('id',ingredient.id):await supabase.from('ingredients').insert(payload).select('id').single();if(res.error){setSaving(false);return alert(res.error.message)}const ingredientId=ingredient?.id||(res.data as any)?.id;if(ingredientId&&(!ingredient||price!==Number(ingredient.current_price)||f.unit_id!==ingredient.unit_id)){await supabase.from('ingredient_prices').insert({ingredient_id:ingredientId,price,unit_id:f.unit_id||null,effective_date:new Date().toISOString().slice(0,10)})}setSaving(false);await onSaved();onClose()}return <Modal title={ingredient?'Modifica ingrediente':'Nuovo ingrediente'} onClose={onClose} wide={Boolean(ingredient)}><div className={ingredient?'ingredientImpactLayout':''}><form onSubmit={save} className="formGrid"><label className="span2">Nome<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label className="span2">Categoria<select required value={f.category} onChange={e=>setF({...f,category:e.target.value})}><option value="">Seleziona</option><option value="Fresco">Fresco</option><option value="Gelo">Gelo</option><option value="Ambiente">Ambiente</option></select></label><label>Prezzo per unità €<input type="number" step="0.0001" min="0" required value={f.current_price} onChange={e=>setF({...f,current_price:e.target.value})}/><small className="fieldHint">Esempio: 15,50 €/kg oppure 0,30 €/pz.</small></label><label>Unità di misura<select required value={f.unit_id} onChange={e=>setF({...f,unit_id:e.target.value})}><option value="">Seleziona</option>{units.map(u=><option key={u.id} value={u.id}>{u.code} — {u.name}</option>)}</select></label><div className="formActions span2"><button type="button" className="ghost" onClick={onClose}>Annulla</button><button className="primary" disabled={saving}>{saving?'Salvataggio…':ingredient?'Salva modifiche':'Salva ingrediente'}</button></div></form>{ingredient&&<aside className="ingredientImpactBox"><div className="ingredientImpactTitle"><span>i</span><strong>Impatto Modifica</strong></div><p>Questo ingrediente è utilizzato nelle seguenti ricette. Modificando il costo, influenzerai il food-cost calcolato per questi piatti.</p><div className="ingredientImpactHead"><strong>Ricette che utilizzano questo ingrediente</strong><b>{usedBy.length}</b></div>{usedBy.length===0?<div className="ingredientImpactEmpty">Questo ingrediente non è ancora utilizzato in alcuna ricetta.</div>:<div className="ingredientImpactList">{usedBy.map(r=><div className="ingredientImpactRecipe" key={r.id}><div><strong>{r.name}</strong>{r.category&&<small>{r.category}</small>}</div></div>)}</div>}</aside>}</div></Modal>}'''
s, n = re.subn(r'function IngredientModal\(\{ingredient,units,onClose,onSaved\}:.*?(?=function RecipeModal)', new_ingredient + '\n', s, count=1, flags=re.S)
if n != 1: raise SystemExit('IngredientModal non trovato')
page.write_text(s)

css=Path('app/ingredient-unit.css')
c=css.read_text()
block='''\n.ingredientImpactLayout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(300px,.8fr);gap:20px;align-items:start;padding-right:22px}\n.ingredientImpactLayout>.formGrid{padding-right:0}\n.ingredientImpactBox{margin-top:20px;border:1px solid #e5e2db;border-left:4px solid var(--accent);border-radius:14px;background:#faf9f6;padding:18px;color:var(--ink)}\n.ingredientImpactTitle{display:flex;align-items:center;gap:10px;font-size:18px}\n.ingredientImpactTitle>span{width:25px;height:25px;border:1.5px solid var(--accent);border-radius:50%;display:grid;place-items:center;color:var(--accent);font-weight:800;font-size:14px}\n.ingredientImpactBox>p{color:var(--muted);font-size:13px;line-height:1.5;margin:14px 0 18px}\n.ingredientImpactHead{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:12px;margin-bottom:7px}\n.ingredientImpactHead b{background:var(--soft);color:var(--accent-dark);border-radius:8px;padding:4px 8px}\n.ingredientImpactList{border-top:1px solid var(--line)}\n.ingredientImpactRecipe{padding:11px 2px;border-bottom:1px solid var(--line)}\n.ingredientImpactRecipe strong{display:block;font-size:13px}\n.ingredientImpactRecipe small{display:block;color:var(--muted);font-size:11px;margin-top:3px}\n.ingredientImpactEmpty{border-top:1px solid var(--line);padding:14px 2px;color:var(--muted);font-size:12px}\n@media(max-width:800px){.ingredientImpactLayout{grid-template-columns:1fr;padding-right:0}.ingredientImpactLayout>.formGrid{padding-right:22px}.ingredientImpactBox{margin:0 22px 22px}}\n'''
if '.ingredientImpactLayout' not in c: css.write_text(c+block)
